function normalize(raw){const base=defaults(),d={...base,...copy(raw||{})};d.theme={...base.theme,...d.theme};d.layout={...base.layout,...d.layout};return d;}
function variants(p){let out=[{label:'Standard',price:Number(p.onSale?p.salePrice:p.price),attributes:{}}];for(const group of (p.options||[]).slice(0,3)){const next=[];for(const prior of out)for(const value of (group.values||[]).slice(0,12)){const attrs={...prior.attributes,[group.name]:value.label};next.push({label:Object.values(attrs).join(' / '),price:prior.price+Number(value.price||0),attributes:attrs,stock:Number(p.stock||0)})}out=next;}return out;}
function productItems(d){return d.items.map(p=>({...copy(p),categories:[p.category],variants:variants(p),seoSlug:p.id,trackStock:p.trackStock}))}
function text(d,path,o){return '<span data-key="'+esc(path)+'"'+(o.edit?' contenteditable="true" spellcheck="false"':'')+'>'+esc(get(d,path)).replace(/\n/g,'<br>')+'</span>'}
function image(src,alt,path){return '<img loading="lazy" src="'+esc(safe(src))+'" alt="'+esc(alt)+'"'+(path?' data-media="'+esc(path)+'"':'')+'>'}
const link=(label,to,cls='')=>'<a class="'+cls+'" href="#'+esc(to)+'">'+label+'</a>';
const input=(name,label,type='text',extra='')=>'<label>'+esc(label)+'<input type="'+type+'" name="'+name+'" '+extra+'></label>';
function header(d,o){const menu=d.menu.filter(m=>m.visible!==false);return (d.announcementEnabled?'<div class="food-announcement">'+text(d,'announcement',o)+'</div>':'')+'<header class="food-header"><a class="food-brand" href="#home">'+(d.logo?image(d.logo,d.brand,'logo'):text(d,'brand',o)+'<small>'+text(d,'tagline',o)+'</small>')+'</a><nav>'+menu.slice(0,4).map(m=>link(esc(m.title),m.id)).join('')+(menu.length>4?'<details class="food-overflow"><summary>More ⌄</summary><div>'+menu.slice(4).map(m=>link(esc(m.title),m.id)).join('')+'</div></details>':'')+'</nav>'+link('Bag (<span data-count>0</span>)','cart','food-bag')+'</header>'}
function footer(d,o){return '<footer class="food-footer"><div><h2>'+text(d,'brand',o)+'</h2><p>'+text(d,'footer',o)+'</p></div><div><h3>Move with us</h3>'+link('Classes & timetable','classes')+link('Memberships','memberships')+link('Personal training','training')+link('My account','dashboard')+'</div><div><h3>Here to help</h3>'+link('Contact','contact')+link('FAQs','faq')+link('Cancellation policy','cancellation')+link('Delivery & returns','delivery')+link('Privacy','privacy')+link('Membership terms','terms')+'</div><small>© '+new Date().getFullYear()+' '+esc(d.brand)+' · Hosted by SGC Network</small></footer>'}
function classCard(d,c,o){const i=d.classes.indexOf(c),coach=d.trainers.find(t=>t.id===c.trainer);return '<article class="fit-class" data-movable="class-'+esc(c.id)+'">'+link(image(c.image,c.name,'classes.'+i+'.image'),'class/'+c.id)+'<h3>'+link(text(d,'classes.'+i+'.name',o),'class/'+c.id)+'</h3><p class="food-muted">'+esc(c.duration)+' min · '+esc(c.level)+' · '+esc(coach?.name||'Studio team')+'</p><div class="food-card-bottom"><b>'+money(c.price)+'</b>'+link('Book class','class/'+c.id,'food-button')+'</div></article>'}
function classGrid(d,classes,o){return '<div class="fit-classes">'+classes.map(c=>classCard(d,c,o)).join('')+'</div>'}
function timetable(d){const days=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'],times=[...new Set(d.schedule.filter(s=>s.active).map(s=>s.time))].sort();return '<div class="fit-schedule"><table><thead><tr><th>Time</th>'+days.map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+times.map(time=>'<tr><th>'+esc(time)+'</th>'+days.map((day,i)=>{const sessions=d.schedule.filter(s=>s.active&&s.day===(i+1)%7&&s.time===time);return '<td class="'+(sessions.length?'':'empty')+'">'+sessions.map(s=>{const c=d.classes.find(c=>c.id===s.classId&&c.active);return c?link(esc(c.name)+'<br><small>'+esc(c.duration)+' min</small>','class/'+c.id):''}).join('<br>')+'</td>'}).join('')+'</tr>').join('')+'</tbody></table></div>'}
function planCards(d,o){return '<label>Billing period<select id="fit-billing"><option value="monthly">Monthly</option><option value="annual">Annual</option></select></label><div class="fit-plans">'+d.plans.filter(p=>p.active).map(p=>{const i=d.plans.indexOf(p);return '<article class="fit-plan '+(p.featured?'featured':'')+'"><small class="food-eyebrow">'+(p.featured?'MOST POPULAR':'YOUR NEXT CHAPTER')+'</small><h3>'+text(d,'plans.'+i+'.name',o)+'</h3><div class="food-price" data-plan-price="'+esc(p.id)+'">'+money(p.monthly)+'</div><p class="food-muted" data-plan-period>per month</p><ul>'+p.benefits.split('\n').filter(Boolean).map(v=>'<li>'+esc(v)+'</li>').join('')+'</ul><p class="food-muted">'+(p.unlimited?'Unlimited eligible classes':Number(p.credits)+' class credits each month')+'</p><a href="#membership/'+esc(p.id)+'/monthly" class="food-button" data-join="'+esc(p.id)+'">Join '+esc(p.name)+'</a></article>'}).join('')+'</div><p class="food-muted">Memberships activate after payment confirmation. '+esc(d.membershipTerms)+'</p>'}
function homeSection(d,id,o){switch(id){case 'hero':return '<section class="food-hero" data-section="hero"><div><small class="food-eyebrow">MOVE · RESTORE · BELONG</small><h1>'+text(d,'heroTitle',o)+'</h1><p>'+text(d,'heroSubtitle',o)+'</p><div class="food-buttons">'+link(text(d,'heroButton',o),d.heroTarget,'food-button')+link(text(d,'heroSecondButton',o),d.heroSecondTarget,'food-button secondary')+'</div></div>'+image(d.heroImage,'Welcoming fitness studio','heroImage')+'</section>';case 'programmes':return '<section class="food-section"><h2>'+text(d,'categoriesTitle',o)+'</h2><div class="food-categories">'+d.categories.filter(c=>c.visible!==false).map(c=>link(image(c.image,c.name,'categories.'+d.categories.indexOf(c)+'.image')+'<span>'+esc(c.name)+'</span>','category/'+c.id)).join('')+'</div></section>';case 'classes':return '<section class="food-section"><div class="food-section-head"><h2>'+text(d,'featuredTitle',o)+'</h2>'+link('View all classes →','classes')+'</div>'+classGrid(d,d.classes.filter(c=>c.active&&c.featured).slice(0,3),o)+'</section>';case 'schedule':return '<section class="food-section" style="background:var(--food-soft)"><h2>Weekly class timetable</h2><p class="food-muted">All times '+esc(d.timezone)+'</p>'+timetable(d)+'</section>';case 'memberships':return '<section class="food-section"><h2>Find your membership</h2>'+planCards(d,o)+'</section>';case 'coaching':return '<section class="food-promo"><div><small class="food-eyebrow">PERSONAL SUPPORT</small><h2>'+text(d,'trainingTitle',o)+'</h2><p>'+text(d,'trainingText',o)+'</p>'+link('Explore personal training','training','food-button secondary')+'</div>'+image(d.aboutImage,'Personal training at the studio','aboutImage')+'</section>';case 'trainers':return '<section class="food-section"><h2>Meet your team</h2><div class="food-grid">'+d.trainers.filter(t=>t.active).map(t=>{const i=d.trainers.indexOf(t);return '<article class="fit-trainer">'+image(t.image,t.name,'trainers.'+i+'.image')+'<h3>'+text(d,'trainers.'+i+'.name',o)+'</h3><p>'+text(d,'trainers.'+i+'.speciality',o)+'</p>'+link('View profile','trainer/'+t.id,'food-button secondary')+'</article>'}).join('')+'</div></section>';case 'gallery':return '<section class="food-section"><h2>A space to belong</h2><div class="food-gallery">'+d.gallery.slice(0,3).map((g,i)=>g.type==='video'?'<video src="'+esc(safe(g.url))+'" controls playsinline></video>':image(g.url,'Studio gallery','gallery.'+i+'.url')).join('')+'</div></section>';case 'newsletter':return '<section class="food-newsletter"><div><h2>'+text(d,'newsletterTitle',o)+'</h2><p>'+text(d,'newsletterText',o)+'</p></div><form data-fit-form="newsletter"><input type="email" name="email" required placeholder="Your email address" aria-label="Email address"><button class="food-button">Subscribe</button><p class="food-status" role="status"></p></form></section>';default:return ''}}
function classPage(d,route,o,r){const c=d.classes.find(c=>c.id===route.slice(6)&&c.active);if(!c)return '<section class="food-section"><h1>Class unavailable</h1>'+link('Explore classes','classes')+'</section>';const i=d.classes.indexOf(c),coach=d.trainers.find(t=>t.id===c.trainer);const memberships=r.history.filter(x=>x.kind==='membership'&&x.status==='Active');return '<section class="food-section"><div class="food-breadcrumb">'+link('← All classes','classes')+'</div><div class="food-two"><div>'+image(c.image,c.name,'classes.'+i+'.image')+'<h1 class="food-headline">'+text(d,'classes.'+i+'.name',o)+'</h1><p>'+text(d,'classes.'+i+'.description',o)+'</p><div class="fit-facts"><span>'+esc(c.intensity)+'</span><span>'+esc(c.level)+'</span><span>'+c.duration+' min</span><span>'+esc(coach?.name||'Studio team')+'</span><span>'+money(c.price)+'</span></div><h3>What to expect</h3><p>'+text(d,'classes.'+i+'.expect',o)+'</p><h3>What to bring</h3><p>'+text(d,'classes.'+i+'.equipment',o)+'</p>'+(c.video?'<video src="'+esc(safe(c.video))+'" controls playsinline></video>':'')+'</div><div class="fit-calendar"><h2>Book your class</h2><form id="fit-booking-form">'+input('date','Select a date','date','required min="'+today()+'"')+'<div id="fit-slots" class="fit-availability"></div><input name="session" type="hidden" required><p id="fit-capacity" class="food-muted">Choose a date to see scheduled sessions.</p>'+input('name','Full name','text','required minlength="2" maxlength="120"')+input('email','Email address','email','required maxlength="254"')+input('phone','Phone number','tel','required maxlength="40"')+'<label>Special requirements (optional)<textarea name="notes" maxlength="1000"></textarea></label>'+(memberships.length?'<label>Use membership<select name="membershipKey"><option value="">Pay per class</option>'+memberships.map(m=>'<option value="'+esc(m.key)+'">'+esc(m.title)+'</option>').join('')+'</select></label>':'')+'<label class="food-check"><input name="consent" type="checkbox" required> I agree to the booking and cancellation policy.</label><p class="food-muted">Cancel at least '+Number(d.cancelHours)+' hours before class. All times '+esc(d.timezone)+'.</p><button class="food-button">'+(r.rescheduleKey?'Confirm reschedule':'Book this class')+'</button><p class="food-status" role="status"></p></form></div></div></section>'}
function classesPage(d,route,o){const category=route.startsWith('category/')?route.slice(9):'';return '<section class="food-section"><h1 class="food-headline">Our classes & programmes</h1><p>Movement for every body. Expert-led classes to help you grow stronger and feel your best.</p><div class="food-filters">'+link('All','classes',category?'':'active')+d.categories.filter(c=>c.visible!==false).map(c=>link(esc(c.name),'category/'+c.id,c.id===category?'active':'')).join('')+'</div><div class="food-search-row"><input id="fit-search" type="search" placeholder="Search classes" aria-label="Search classes"><select id="fit-level" aria-label="Class level"><option value="">All levels</option><option>Beginner</option><option>Intermediate</option></select><select id="fit-trainer" aria-label="Trainer"><option value="">All trainers</option>'+d.trainers.map(t=>'<option value="'+esc(t.id)+'">'+esc(t.name)+'</option>').join('')+'</select></div><div id="fit-class-results">'+classGrid(d,d.classes.filter(c=>c.active&&(!category||c.category===category)),o)+'</div><h2 style="margin-top:40px">Weekly class timetable</h2>'+timetable(d)+'</section>'}
function coachingPage(d,route,o){return '<section class="food-section"><h1 class="food-headline">'+text(d,route==='training'?'trainingTitle':'coachingTitle',o)+'</h1><p>'+text(d,route==='training'?'trainingText':'coachingText',o)+'</p><div class="fit-plans">'+d.coachingPackages.map((p,i)=>'<article class="fit-plan"><h3>'+text(d,'coachingPackages.'+i+'.name',o)+'</h3><p>'+text(d,'coachingPackages.'+i+'.description',o)+'</p><b class="food-price">'+money(p.price)+'</b><p>'+p.sessions+' sessions</p></article>').join('')+'</div><div class="food-two"><div>'+image(d.aboutImage,'Supportive personal coaching','aboutImage')+'<h2>Personal guidance. Your pace.</h2><p>'+esc(d.coachingServices.join(' · '))+'</p></div><div class="food-box"><h2>Book a consultation</h2><form data-fit-form="coaching">'+contactInputs()+'<label>Package<select name="package">'+d.coachingPackages.map(p=>'<option value="'+esc(p.id)+'">'+esc(p.name)+' · '+money(p.price)+'</option>').join('')+'</select></label><label>Choose coach<select name="trainer">'+d.trainers.filter(t=>t.active).map(t=>'<option value="'+esc(t.id)+'">'+esc(t.name)+'</option>').join('')+'</select></label><label>Session format<select name="format"><option>Studio</option><option>Online</option></select></label>'+input('date','Preferred date','date','required min="'+today()+'"')+'<label>Your goals<textarea name="notes" maxlength="1500" required></textarea></label><button class="food-button">Request consultation</button><p class="food-muted">The studio will confirm coach availability and payment details.</p><p class="food-status" role="status"></p></form></div></div></section>'}
const contactInputs=()=>input('name','Full name','text','required minlength="2" maxlength="120"')+input('email','Email address','email','required maxlength="254"')+input('phone','Phone number','tel','required maxlength="40"');
function productCard(d,p,o){return '<article class="food-card">'+link(image(p.images[0],p.name,'items.'+d.items.indexOf(p)+'.images.0'),'item/'+p.id)+'<h3>'+link(esc(p.name),'item/'+p.id)+'</h3><div class="food-card-bottom"><b>'+money(p.onSale?p.salePrice:p.price)+'</b>'+link('View item','item/'+p.id,'food-button secondary')+'</div></article>'}
function productPage(d,route,o){const p=d.items.find(p=>p.id===route.slice(5)&&p.active);if(!p)return '<section class="food-section"><h1>Product unavailable</h1></section>';const i=d.items.indexOf(p);return '<section class="food-section"><div class="food-breadcrumb">'+link('← Back to shop','shop')+'</div><div class="food-item-detail"><div><div id="fit-product-image">'+image(p.images[0],p.name,'items.'+i+'.images.0')+'</div><div class="food-thumbs">'+p.images.map((src,j)=>'<button data-image="'+j+'">'+image(src,p.name)+'</button>').join('')+'</div>'+(p.video?'<video src="'+esc(safe(p.video))+'" controls playsinline></video>':'')+'</div><form id="fit-product-form"><h1 class="food-headline">'+text(d,'items.'+i+'.name',o)+'</h1><div id="fit-product-price" class="food-price">'+money(p.onSale?p.salePrice:p.price)+'</div><p>'+text(d,'items.'+i+'.description',o)+'</p>'+p.options.map((g,j)=>'<label>'+esc(g.name)+'<select name="option'+j+'">'+g.values.map((v,k)=>'<option value="'+k+'">'+esc(v.label)+(Number(v.price)?' +'+money(v.price):'')+'</option>').join('')+'</select></label>').join('')+input('quantity','Quantity','number','required min="1" max="99" value="1"')+'<button class="food-button">Add to cart</button><p class="food-status" role="status"></p><details class="food-faq"><summary>Product details</summary><p>'+text(d,'items.'+i+'.details',o)+'</p></details><details class="food-faq"><summary>Shipping & delivery</summary><p>'+text(d,'items.'+i+'.shipping',o)+'</p></details></form></div></section>'}
function cartLines(d,r){return r.cart.map((l,i)=>{const p=d.items.find(p=>p.id===l.productId),v=p?variants(p)[l.variantIndex]:null;return {...l,i,p,v,total:Number(v?.price||0)*l.quantity,available:!!p?.active&&!!v}})}
function checkoutPage(d,route,o,r){const membership=route.startsWith('membership/'),parts=route.split('/'),plan=membership?d.plans.find(p=>p.id===parts[1]&&p.active):null,annual=parts[2]==='annual';if(membership&&!plan)return '<section class="food-section"><h1>Membership unavailable</h1></section>';const lines=cartLines(d,r),subtotal=membership?Number(annual?plan.annual:plan.monthly):lines.reduce((a,l)=>a+l.total,0);if(!membership&&!lines.length)return '<section class="food-section"><h1>Your cart</h1><p>Your cart is empty.</p>'+link('Explore our shop','shop','food-button')+'</section>';const summary=membership?'<h2>'+esc(plan.name)+' membership</h2><p>'+ (annual?'Annual':'Monthly')+' membership period</p><p>'+esc(plan.benefits).replace(/\n/g,'<br>')+'</p>':lines.map(l=>'<article class="food-cart-row">'+image(l.p?.images[0],l.p?.name)+'<div><h3>'+esc(l.p?.name||'Unavailable product')+'</h3><p class="food-muted">'+esc(l.v?.label||'Option unavailable')+'</p><input data-qty="'+l.i+'" type="number" value="'+l.quantity+'" min="1" max="99" aria-label="Quantity"><button data-remove="'+l.i+'">Remove</button></div><b>'+money(l.total)+'</b></article>').join('');const form='<form id="fit-checkout-form">'+contactInputs()+(membership?input('startDate','Preferred start date','date','min="'+today()+'"'):'<label>Delivery method<select name="fulfilment">'+(d.collectionEnabled?'<option>Collection</option>':'')+(d.deliveryEnabled?'<option>Delivery</option>':'')+'</select></label>'+input('address','Delivery address','text','maxlength="500"'))+'<label>Payment method<select name="payment">'+d.paymentMethods.split(',').map(v=>'<option>'+esc(v.trim())+'</option>').join('')+'</select></label><label>Notes<textarea name="notes" maxlength="1000"></textarea></label>'+(membership?'<label class="food-check"><input name="terms" type="checkbox" required> I accept the membership terms and understand activation follows payment confirmation.</label><p class="food-muted">'+esc(d.membershipTerms)+'</p>':'')+'<div class="food-total"><span>Total</span><b id="fit-checkout-total">'+money(subtotal)+'</b></div><p class="food-muted">'+esc(d.checkoutText)+'</p><button class="food-button">'+(membership?'Request membership':'Place order')+'</button><p class="food-status" role="status"></p></form>';return '<section class="food-section"><h1 class="food-headline">'+(route==='cart'?'Your cart':membership?'Start your membership':'Checkout')+'</h1><div class="food-two"><div>'+summary+'<div class="food-total"><span>Subtotal</span><b>'+money(subtotal)+'</b></div></div><div class="food-box">'+(route==='cart'?'<h2>Your order</h2><p>Delivery fees are added at checkout.</p>'+link('Continue to checkout','checkout','food-button'):form)+'</div></div></section>'}
function dashboard(d,r){const memberships=r.history.filter(x=>x.kind==='membership'),active=memberships.find(m=>m.status==='Active'),bookings=r.history.filter(x=>['booking','coaching'].includes(x.kind)),orders=r.history.filter(x=>x.kind==='order');return '<section class="food-section"><div class="food-section-head"><div><small class="food-eyebrow">YOUR MEMBER SPACE</small><h1 class="food-headline">Welcome'+(r.profile.name?', '+esc(r.profile.name.split(' ')[0]):' to your studio')+'.</h1></div><button class="food-button secondary" id="fit-refresh">Refresh records</button></div><p class="food-muted">Your bookings and memberships from this device appear here. Keep your booking reference private.</p><div class="fit-dashboard-grid"><div class="fit-dashboard-card"><small>MEMBERSHIP</small><b>'+esc(active?.title||memberships[0]?.status||'Not joined')+'</b><span>'+esc(active?.status||'Choose a membership to get started')+'</span></div><div class="fit-dashboard-card"><small>CLASS CREDITS</small><b>'+(active?(active.unlimited?'Unlimited':Number(active.remainingCredits||0)):'—')+'</b><span>'+(active?.endsAt?'Period ends '+esc(active.endsAt.slice(0,10)):'Credits appear after activation')+'</span></div><div class="fit-dashboard-card"><small>MY BOOKINGS</small><b>'+bookings.filter(b=>b.status==='Confirmed').length+'</b><span>Confirmed bookings</span></div></div><div class="fit-dashboard-tabs">'+['Bookings','Memberships','Orders','Training plan','Progress','Profile'].map(t=>'<button data-dashboard-tab="'+t+'">'+t+'</button>').join('')+'</div><div id="fit-dashboard-panel"></div><template id="fit-bookings-template">'+(bookings.length?bookings.map(b=>'<article class="fit-booking"><h3>'+esc(b.title)+'</h3><p>'+esc(b.date||'')+' · '+esc(b.time||'')+' · '+esc(b.status)+'</p><p class="food-muted">'+esc(b.number)+' · '+money(b.total)+' · Payment '+esc(b.paymentStatus||'pending')+'</p><div class="fit-booking-actions"><button data-calendar="'+esc(b.key)+'">Add to calendar</button>'+(b.kind==='booking'&&b.status==='Confirmed'?'<button data-reschedule="'+esc(b.key)+'">Reschedule</button><button data-cancel="'+esc(b.key)+'">Cancel booking</button>':'')+'</div></article>').join(''):'<p>No class bookings yet.</p>'+link('Book a class','classes','food-button'))+'</template><template id="fit-memberships-template">'+(memberships.length?memberships.map(m=>'<article class="fit-booking"><h3>'+esc(m.title)+'</h3><p>'+esc(m.status)+' · '+money(m.total)+'</p><p class="food-muted">'+esc(m.number)+' · Payment '+esc(m.paymentStatus||'pending')+'</p>'+(m.endsAt?'<p>Period ends '+esc(m.endsAt.slice(0,10))+'</p>':'<p>Activation follows payment confirmation by the studio.</p>')+'</article>').join(''):'<p>No membership yet.</p>'+link('Explore memberships','memberships','food-button'))+'</template><template id="fit-orders-template">'+(orders.length?orders.map(x=>'<article class="fit-booking"><h3>'+esc(x.title||x.number)+'</h3><p>'+money(x.total)+' · '+esc(x.status)+' · Payment '+esc(x.paymentStatus||'pending')+'</p></article>').join(''):'<p>No shop orders yet.</p>')+'</template></section>'}
function body(d,route,o,r){if(route==='home')return d.sections.filter(x=>!d.hiddenSections.includes(x)).map(id=>homeSection(d,id,o)).join('');if(['classes','book','categories','schedule'].includes(route)||route.startsWith('category/'))return classesPage(d,route,o);if(route.startsWith('class/'))return classPage(d,route,o,r);if(route==='memberships')return '<section class="food-section"><h1 class="food-headline">Choose your membership</h1><p>Flexible options for every journey.</p>'+planCards(d,o)+'</section>';if(route.startsWith('membership/')||['cart','checkout'].includes(route))return checkoutPage(d,route,o,r);if(['training','coaching'].includes(route))return coachingPage(d,route,o);if(route==='shop'||route.startsWith('shop-category/')){const cat=route.split('/')[1];return '<section class="food-section"><h1 class="food-headline">Move well. Live well.</h1><div class="food-filters">'+link('All','shop')+d.shopCategories.map(c=>link(esc(c.name),'shop-category/'+c.id)).join('')+'</div><div class="food-grid">'+d.items.filter(p=>p.active&&(!cat||p.category===cat)).map(p=>productCard(d,p,o)).join('')+'</div></section>'}if(route.startsWith('item/'))return productPage(d,route,o);if(route==='about')return '<section class="food-section food-story">'+image(d.aboutImage,'Vital studio','aboutImage')+'<div><h1 class="food-headline">'+text(d,'aboutTitle',o)+'</h1><p>'+text(d,'about',o)+'</p>'+link('Meet our trainers','trainers','food-button')+'</div></section>';if(route==='trainers')return homeSection(d,'trainers',o);if(route.startsWith('trainer/')){const t=d.trainers.find(x=>x.id===route.slice(8));if(!t)return '<section class="food-section"><h1>Trainer unavailable</h1></section>';const i=d.trainers.indexOf(t);return '<section class="food-section food-story">'+image(t.image,t.name,'trainers.'+i+'.image')+'<div><h1>'+text(d,'trainers.'+i+'.name',o)+'</h1><p>'+text(d,'trainers.'+i+'.speciality',o)+'</p><p>'+text(d,'trainers.'+i+'.credentials',o)+'</p><p>'+text(d,'trainers.'+i+'.bio',o)+'</p>'+link('Book a consultation','training','food-button')+'</div></section>'}if(route==='gallery')return '<section class="food-section"><h1 class="food-headline">Our studio, your space.</h1><div class="food-gallery">'+d.gallery.map((g,i)=>g.type==='video'?'<video src="'+esc(safe(g.url))+'" controls playsinline></video>':image(g.url,'Studio gallery','gallery.'+i+'.url')).join('')+'</div></section>';if(route==='contact')return '<section class="food-section"><h1 class="food-headline">Let’s connect.</h1><div class="food-two"><div><h2>Visit the studio</h2><p>'+text(d,'address',o)+'</p><p>'+text(d,'email',o)+'</p><p>'+text(d,'phone',o)+'</p><h3>Opening hours</h3><p>'+text(d,'hours',o)+'</p>'+(d.address?'<a class="food-button secondary" target="_blank" rel="noopener" href="https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(d.address)+'">Get directions ↗</a>':'')+(d.whatsapp?'<p><a class="food-button secondary" href="https://wa.me/'+esc(d.whatsapp.replace(/\D/g,''))+'" target="_blank" rel="noopener">Chat on WhatsApp</a></p>':'')+'</div><div class="food-box"><form data-fit-form="contact">'+contactInputs()+'<label>Your message<textarea name="notes" required maxlength="2000"></textarea></label><button class="food-button">Send enquiry</button><p class="food-status" role="status"></p></form></div></div></section>';if(['dashboard','orders'].includes(route))return dashboard(d,r);if(route==='faq')return '<section class="food-section"><h1 class="food-headline">Your questions, answered.</h1>'+d.faq.map((f,i)=>'<details class="food-faq"><summary>'+text(d,'faq.'+i+'.question',o)+'</summary><p>'+text(d,'faq.'+i+'.answer',o)+'</p></details>').join('')+'</section>';if(['delivery','refunds','privacy','terms','cancellation'].includes(route))return '<section class="food-section"><h1 class="food-headline">'+esc(route[0].toUpperCase()+route.slice(1))+'</h1><p>'+text(d,'policy'+route[0].toUpperCase()+route.slice(1),o)+'</p></section>';if(route==='confirmation'){const x=r.history[0];return '<section class="food-section"><div class="food-box"><small class="food-eyebrow">YOUR NEXT CHAPTER</small><h1 class="food-headline">'+(x?.kind==='booking'?'You’re booked!':'Thank you. Your request is received.')+'</h1><p>'+esc(x?.title||'')+'</p><p>'+esc(x?.date||'')+' '+esc(x?.time||'')+'</p><p>'+esc(x?.number||'')+' · '+money(x?.total)+'</p><p>'+esc(x?.status||'Received')+' · Payment '+esc(x?.paymentStatus||'pending')+'</p>'+link('Open my account','dashboard','food-button')+'</div></section>'}const p=d.customPages.find(p=>p.id===route);return '<section class="food-section"><h1 class="food-headline">'+esc(p?.title||'Page not found')+'</h1></section>'}
function blocks(d,route,o){const p=d.pageContent[route];return !p?'':'<section class="food-section" style="background:'+esc(p.background||d.theme.background)+';color:'+esc(p.color||d.theme.ink)+'">'+p.blocks.map((b,i)=>{const path='pageContent.'+route+'.blocks.'+i;return '<div class="food-block">'+(b.type==='image'?image(b.url,'Page image',path+'.url'):b.type==='video'?'<video src="'+esc(safe(b.url))+'" controls playsinline></video>':b.type==='button'?link(text(d,path+'.text',o),b.target||'classes','food-button'):b.type==='heading'?'<h2>'+text(d,path+'.text',o)+'</h2>':'<p>'+text(d,path+'.text',o)+'</p>')+'</div>'}).join('')+'</section>'}
function runtime(slug='fitness-preview'){let s={};try{s=JSON.parse(localStorage.getItem('sgc-fitness-customer:'+slug)||'{}')}catch{}const r={cart:s.cart||[],history:s.history||[],profile:s.profile||{},habits:s.habits||{},checkoutKey:s.checkoutKey||null,rescheduleKey:null};r.save=()=>{try{localStorage.setItem('sgc-fitness-customer:'+slug,JSON.stringify({cart:r.cart,history:r.history,profile:r.profile,habits:r.habits,checkoutKey:r.checkoutKey}))}catch{}};return r}
function apply(host,d,route,o){host.classList.add('food-site');for(const [k,v]of Object.entries(d.theme))if(['background','ink','accent','olive','soft'].includes(k))host.style.setProperty('--food-'+(k==='background'?'bg':k),/^#[\da-f]{6}$/i.test(v)?v:'#fffef8');host.style.setProperty('--food-radius',Math.min(40,Math.max(0,Number(d.theme.radius)))+'px');host.style.setProperty('--food-heading',['Playfair Display','Georgia','DM Sans','Arial'].includes(d.theme.heading)?d.theme.heading:'Georgia');host.style.fontFamily=['DM Sans','Georgia','Playfair Display','Arial'].includes(d.theme.body)?'"'+d.theme.body+'"':'Arial';const device=o.device||(innerWidth<650?'mobile':innerWidth<950?'tablet':'desktop');for(const [key,pos]of Object.entries(d.layout[device]||{})){if(!key.startsWith(route+'|'))continue;try{const el=host.querySelector(key.slice(route.length+1));if(el){el.style.position='relative';el.style.left=Number(pos.x||0)+'px';el.style.top=Number(pos.y||0)+'px';el.style.zIndex='2'}}catch{}}for(const [selector,spec]of Object.entries(d.elementEdits?.[route]||{})){try{const el=host.querySelector(selector);if(!el)continue;if(spec.text!==undefined&&!el.children.length)el.textContent=spec.text;if(spec.src&&['IMG','VIDEO'].includes(el.tagName))el.src=safe(spec.src);for(const key of ['color','backgroundColor','fontSize','textAlign','width','borderRadius','padding'])if(spec[key]!==undefined)el.style[key]=spec[key]}catch{}}}
function render(host,raw,route='home',o={}){const d=normalize(raw),r=o.runtime||runtime(o.slug);host.innerHTML=header(d,o)+'<div class="food-content">'+body(d,route,o,r)+blocks(d,route,o)+'</div>'+footer(d,o)+'<nav class="fit-mobile-nav">'+link('Home','home')+link('Classes','classes')+link('Book','book')+link('Account','dashboard')+'</nav>';apply(host,d,route,o);bind(host,d,route,{...o,runtime:r});return host}
async function request(body){const res=await fetch('https://bxpexanyoyubxeqqlggh.supabase.co/functions/v1/fitness-business',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const data=await res.json();if(!res.ok||data.error)throw Error(data.error||'Please try again.');return data}
function bind(host,d,route,o){const r=o.runtime,navigate=to=>{if(o.navigate)o.navigate(to);else location.hash=to},redraw=()=>render(host,d,route,o);const linkEvents=scope=>scope.querySelectorAll('a[href^="#"]').forEach(a=>a.onclick=e=>{if(e.target.closest('[contenteditable=true]'))return;e.preventDefault();navigate(a.getAttribute('href').slice(1))});linkEvents(host);host.querySelectorAll('[data-key][contenteditable]').forEach(el=>{el.oninput=()=>o.onEdit?.(el.dataset.key,el.innerText);el.onpaste=e=>{e.preventDefault();document.execCommand('insertText',false,e.clipboardData.getData('text/plain'))}});host.querySelectorAll('[data-media]').forEach(el=>el.ondblclick=()=>o.onMedia?.(el.dataset.media));host.querySelectorAll('[data-count]').forEach(el=>el.textContent=r.cart.reduce((a,l)=>a+l.quantity,0));const search=host.querySelector('#fit-search');if(search){const update=()=>{const cat=route.startsWith('category/')?route.slice(9):'',term=search.value.toLowerCase(),level=host.querySelector('#fit-level').value,trainer=host.querySelector('#fit-trainer').value;const result=host.querySelector('#fit-class-results');const found=d.classes.filter(c=>c.active&&(!cat||c.category===cat)&&(!level||c.level===level||c.level==='All levels')&&(!trainer||c.trainer===trainer)&&(c.name+' '+c.description).toLowerCase().includes(term));result.innerHTML=found.length?classGrid(d,found,o):'<p>No matching classes. Try another filter.</p>';linkEvents(result)};[search,host.querySelector('#fit-level'),host.querySelector('#fit-trainer')].forEach(el=>el.oninput=update)}
const billing=host.querySelector('#fit-billing');if(billing)billing.onchange=()=>{d.plans.forEach(p=>{const price=host.querySelector('[data-plan-price="'+p.id+'"]'),join=host.querySelector('[data-join="'+p.id+'"]');if(price)price.textContent=money(p[billing.value]);if(join)join.href='#membership/'+p.id+'/'+billing.value});host.querySelectorAll('[data-plan-period]').forEach(el=>el.textContent=billing.value==='annual'?'per year':'per month')};
const booking=host.querySelector('#fit-booking-form');if(booking){const c=d.classes.find(c=>c.id===route.slice(6));let key=uid();const date=booking.elements.date;for(const name of ['name','email','phone'])booking.elements[name].value=r.profile[name]||'';
const showSlots=async()=>{const slots=d.schedule.filter(s=>s.active&&s.classId===c.id&&s.day===new Date(date.value+'T12:00:00+02:00').getUTCDay()),area=host.querySelector('#fit-slots'),status=host.querySelector('#fit-capacity');area.replaceChildren();booking.elements.session.value='';if(!slots.length||d.blockedDates.split(',').map(v=>v.trim()).includes(date.value)){status.textContent='No scheduled sessions on this date. Please choose another date.';return}let availability=[];if(!o.preview){try{const result=await request({action:'availability',slug:o.slug,classId:c.id,date:date.value});availability=result.sessions||[]}catch(e){status.textContent=e.message;return}}for(const s of slots){const available=o.preview?c.capacity:availability.find(a=>a.id===s.id)?.remaining||0;const button=document.createElement('button');button.type='button';button.textContent=s.time+' · '+available+' spaces';button.disabled=available<1;button.onclick=()=>{booking.elements.session.value=s.id;area.querySelectorAll('button').forEach(b=>b.classList.toggle('selected',b===button));status.textContent=available+' spaces available · '+d.timezone};area.append(button)}status.textContent=o.preview?'Preview capacity. Availability is checked when booking the published website.':'Select an available session.';};date.onchange=showSlots;date.value=today();showSlots();booking.onsubmit=async e=>{e.preventDefault();const status=booking.querySelector('.food-status');if(!booking.elements.session.value){status.textContent='Choose a session time.';return}if(o.preview){status.textContent='Preview only — no booking was submitted.';return}const button=booking.querySelector('button[type=submit],button.food-button');button.disabled=true;try{const fields=Object.fromEntries(new FormData(booking));const result=await request({action:r.rescheduleKey?'reschedule':'submit',kind:'booking',slug:o.slug,key:r.rescheduleKey||key,classId:c.id,fields,membershipKey:fields.membershipKey||null});r.profile={...r.profile,name:fields.name,email:fields.email,phone:fields.phone};r.history=r.history.filter(x=>x.key!==(r.rescheduleKey||key));r.history.unshift({...result.record,key:r.rescheduleKey||key});r.rescheduleKey=null;r.save();navigate('confirmation')}catch(e){status.textContent=e.message}finally{button.disabled=false}};}
const product=host.querySelector('#fit-product-form');if(product){const p=d.items.find(p=>p.id===route.slice(5)),vs=variants(p);const selected=()=>{const attrs={};p.options.forEach((g,i)=>attrs[g.name]=g.values[Number(product.elements['option'+i].value)].label);return vs.findIndex(v=>JSON.stringify(v.attributes)===JSON.stringify(attrs))};product.onchange=()=>host.querySelector('#fit-product-price').textContent=money(vs[selected()].price);product.onsubmit=e=>{e.preventDefault();const index=selected(),quantity=Number(product.elements.quantity.value),existing=r.cart.find(l=>l.productId===p.id&&l.variantIndex===index);if(existing)existing.quantity+=quantity;else r.cart.push({productId:p.id,variantIndex:index,quantity});r.checkoutKey=null;r.save();host.querySelectorAll('[data-count]').forEach(el=>el.textContent=r.cart.reduce((a,l)=>a+l.quantity,0));product.querySelector('.food-status').textContent='Added to your bag.'};host.querySelectorAll('[data-image]').forEach(b=>b.onclick=()=>host.querySelector('#fit-product-image').innerHTML=image(p.images[Number(b.dataset.image)],p.name))}
host.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{r.cart.splice(Number(b.dataset.remove),1);r.checkoutKey=null;r.save();redraw()});host.querySelectorAll('[data-qty]').forEach(el=>el.onchange=()=>{const quantity=Number(el.value);if(!Number.isInteger(quantity)||quantity<1||quantity>99)return;r.cart[Number(el.dataset.qty)].quantity=quantity;r.checkoutKey=null;r.save();redraw()});
const checkout=host.querySelector('#fit-checkout-form');if(checkout){const membership=route.startsWith('membership/'),parts=route.split('/');for(const name of ['name','email','phone'])checkout.elements[name].value=r.profile[name]||'';if(!membership){const update=()=>host.querySelector('#fit-checkout-total').textContent=money(cartLines(d,r).reduce((a,l)=>a+l.total,0)+(checkout.elements.fulfilment.value==='Delivery'?Number(d.deliveryFee):0));checkout.elements.fulfilment.onchange=update;update()}checkout.onsubmit=async e=>{e.preventDefault();const status=checkout.querySelector('.food-status');if(o.preview){status.textContent='Preview only — no order or membership was submitted.';return}const fields=Object.fromEntries(new FormData(checkout));if(fields.fulfilment==='Delivery'&&!fields.address.trim()){status.textContent='Enter your delivery address.';return}const button=checkout.querySelector('button.food-button');button.disabled=true;r.checkoutKey??=uid();r.save();try{const result=await request({action:'submit',kind:membership?'membership':'order',slug:o.slug,key:r.checkoutKey,planId:parts[1],billing:parts[2],fields,items:r.cart});r.profile={...r.profile,name:fields.name,email:fields.email,phone:fields.phone};r.history.unshift({...result.record,key:r.checkoutKey});if(!membership)r.cart=[];r.checkoutKey=null;r.save();navigate('confirmation')}catch(e){status.textContent=e.message}finally{button.disabled=false}};}
host.querySelectorAll('[data-fit-form]').forEach(form=>{let key=uid();form.onsubmit=async e=>{e.preventDefault();const status=form.querySelector('.food-status');if(o.preview){status.textContent='Preview only — this request has not been sent.';return}const button=form.querySelector('button');button.disabled=true;try{const result=await request({action:'submit',kind:form.dataset.fitForm,slug:o.slug,key,fields:Object.fromEntries(new FormData(form))});if(form.dataset.fitForm==='coaching'){r.history.unshift({...result.record,key});r.save()}status.textContent='Thank you. Your request has been received.';form.reset();key=uid()}catch(e){status.textContent=e.message}finally{button.disabled=false}}});
if(route==='dashboard'||route==='orders')bindDashboard(host,d,r,o,navigate,redraw);
}
function bindDashboard(host,d,r,o,navigate,redraw){const panel=host.querySelector('#fit-dashboard-panel');const show=tab=>{if(['Bookings','Memberships','Orders'].includes(tab)){panel.innerHTML=host.querySelector('#fit-'+tab.toLowerCase()+'-template').innerHTML;panel.querySelectorAll('a').forEach(a=>a.onclick=e=>{e.preventDefault();navigate(a.getAttribute('href').slice(1))});bindActions();}else if(tab==='Training plan')panel.innerHTML='<h2>Your studio training guide</h2><p class="food-muted">A general guide from your studio. Adapt it with your coach to suit your experience and needs.</p><p>'+esc(d.trainingPlan).replace(/\n/g,'<br>')+'</p>';else if(tab==='Profile'){panel.innerHTML='<h2>Your profile on this device</h2><form id="fit-profile">'+input('name','Name','text','maxlength="120" value="'+esc(r.profile.name||'')+'"')+input('email','Email','email','value="'+esc(r.profile.email||'')+'"')+input('phone','Phone','tel','value="'+esc(r.profile.phone||'')+'"')+'<label>Your movement goals<textarea name="goals" maxlength="1000">'+esc(r.profile.goals||'')+'</textarea></label><button class="food-button">Save profile</button><p class="food-status"></p></form>';panel.querySelector('form').onsubmit=e=>{e.preventDefault();r.profile=Object.fromEntries(new FormData(e.currentTarget));r.save();panel.querySelector('.food-status').textContent='Saved on this device.'}}else{const key=today(),entry=r.habits[key]||{};panel.innerHTML='<h2>Your daily habits</h2><p class="food-muted">A private tracker on this device. Tick what you completed today.</p><div class="fit-habits">'+['Movement','Hydration','Recovery'].map(name=>'<label><input type="checkbox" data-habit="'+name+'" '+(entry[name]?'checked':'')+'>'+name+'</label>').join('')+'</div><div class="fit-bar-chart">'+Array.from({length:7},(_,i)=>{const date=new Date(Date.now()-(6-i)*86400000).toLocaleDateString('en-CA',{timeZone:'Africa/Johannesburg'}),count=Object.values(r.habits[date]||{}).filter(Boolean).length;return '<div><span style="height:'+(count/3*80+4)+'px"></span>'+esc(date.slice(5))+'</div>'}).join('')+'</div>';panel.querySelectorAll('[data-habit]').forEach(cb=>cb.onchange=()=>{r.habits[key]??={};r.habits[key][cb.dataset.habit]=cb.checked;r.save();show('Progress')})}};
const bindActions=()=>{panel.querySelectorAll('[data-cancel]').forEach(b=>b.onclick=()=>{if(o.preview){b.textContent='Preview only';return}const confirm=document.createElement('div');confirm.className='fit-owner-note';confirm.textContent='Cancel this booking? ';const yes=document.createElement('button');yes.textContent='Yes, cancel';const no=document.createElement('button');no.textContent='Keep booking';no.onclick=()=>confirm.remove();yes.onclick=async()=>{yes.disabled=true;try{const result=await request({action:'cancel',slug:o.slug,key:b.dataset.cancel});Object.assign(r.history.find(x=>x.key===b.dataset.cancel),result.record);r.save();redraw()}catch(e){confirm.textContent=e.message}};confirm.append(yes,no);b.parentElement.append(confirm)});panel.querySelectorAll('[data-reschedule]').forEach(b=>b.onclick=()=>{const record=r.history.find(x=>x.key===b.dataset.reschedule);r.rescheduleKey=record.key;navigate('class/'+record.classId)});panel.querySelectorAll('[data-calendar]').forEach(b=>b.onclick=()=>{const record=r.history.find(x=>x.key===b.dataset.calendar);if(!record?.date||!record?.time)return;const start=new Date(record.date+'T'+record.time+':00+02:00'),end=new Date(start.getTime()+Number(record.duration||45)*60000),stamp=date=>date.toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');const calendar='BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//SGC//Fitness//EN\r\nBEGIN:VEVENT\r\nUID:'+record.key+'@sgcnetwork.co.za\r\nDTSTART:'+stamp(start)+'\r\nDTEND:'+stamp(end)+'\r\nSUMMARY:'+String(record.title).replace(/[\r\n,;]/g,' ')+'\r\nEND:VEVENT\r\nEND:VCALENDAR';const url=URL.createObjectURL(new Blob([calendar],{type:'text/calendar'}));const a=document.createElement('a');a.href=url;a.download='class-booking.ics';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)})};host.querySelectorAll('[data-dashboard-tab]').forEach(b=>b.onclick=()=>show(b.dataset.dashboardTab));host.querySelector('#fit-refresh').onclick=async()=>{if(o.preview){host.querySelector('#fit-refresh').textContent='Preview records';return}const button=host.querySelector('#fit-refresh');button.disabled=true;try{for(const record of r.history){const result=await request({action:'track',slug:o.slug,key:record.key});Object.assign(record,result.record)}r.save();redraw()}catch(e){button.textContent=e.message}finally{button.disabled=false}};show('Bookings');}
